.gam-br .gam-ghost { height: 30px; font-size: 12.5px; }

/* ---------- Follow-ups ---------- */
.gam-fu { display: flex; flex-direction: column; gap: 8px; }
.gam-fu-label { font-size: 12px; font-weight: 500; color: var(--am-mute); }
.gam-fu-list { display: flex; flex-direction: column; gap: 6px; }
.gam-fu-list button { display: flex; align-items: center; justify-content: space-between; gap: 10px; width: 100%; padding: 10px 12px; border: 0; border-radius: 12px; font: inherit; font-size: 14px; text-align: left; color: var(--glass-fg); background: var(--am-soft); box-shadow: inset 0 0 0 1px var(--am-line); cursor: pointer; animation: gam-rise 0.4s var(--am-out) calc(var(--k) * 70ms) backwards; transition: background 0.2s, transform 0.3s var(--am-spring); }
.gam-fu-list button svg { flex: none; color: var(--am-mute); transition: transform 0.3s var(--am-spring), color 0.2s; }
.gam-fu-list button:hover { background: color-mix(in srgb, var(--am-c) 8%, var(--am-s)); }
.gam-fu-list button:hover svg { transform: translateX(3px); color: var(--am-c); }
.gam-fu-list button:active { transform: scale(0.98); }

/* ---------- Ask about a selection ---------- */
.gam-sel { position: relative; }
.gam-sel ::selection { background: color-mix(in srgb, var(--am-c) 25%, transparent); }
.gam-sel-bar { position: absolute; z-index: 20; display: flex; gap: 2px; padding: 3px; border-radius: 12px; transform: translate(-50%, calc(-100% - 8px)); background: #18181b; box-shadow: 0 10px 24px -10px rgb(0 0 0 / 0.5); animation: gam-pop 0.22s var(--am-spring); }
