.gam-sel-bar button { display: inline-flex; align-items: center; gap: 5px; height: 30px; padding: 0 10px; border: 0; border-radius: 9px; font: inherit; font-size: 13px; font-weight: 500; color: #fff; background: none; cursor: pointer; }
.gam-sel-bar button:hover { background: rgb(255 255 255 / 0.12); }
:root[data-glass-mode="dark"] .gam-sel-bar { background: #f2f2f5; } :root[data-glass-mode="dark"] .gam-sel-bar::after { border-top-color: #f2f2f5; } :root[data-glass-mode="dark"] .gam-sel-bar button { color: #111; } :root[data-glass-mode="dark"] .gam-sel-bar button:hover { background: rgb(0 0 0 / 0.08); }

/* ---------- Errors ---------- */
.gam-err { --t: #e5484d; display: flex; align-items: center; gap: 12px; padding: 12px 12px 12px 14px; border-radius: 16px; background: color-mix(in srgb, var(--t) 7%, var(--am-s)); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--t) 22%, transparent); animation: gam-rise 0.35s var(--am-out); }
