@media (max-width: 520px) { .gam-err { flex-wrap: wrap; } .gam-err-acts { width: 100%; justify-content: flex-end; } }

/* ---------- Chat history ---------- */
.gam-hist { width: 100%; max-width: 300px; padding: 4px; border-radius: 24px; text-align: left; background: linear-gradient(180deg, #f2f2f4, #e9e9ec); box-shadow: 0 0 0 1px rgb(0 0 0 / 0.06), 0 1px 2px rgb(0 0 0 / 0.04), 0 24px 48px -28px rgb(0 0 0 / 0.38); }
:root[data-glass-mode="dark"] .gam-hist { background: linear-gradient(180deg, #1b1b1f, #121215); box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.04), 0 0 0 1px rgb(255 255 255 / 0.06), 0 24px 48px -22px rgb(0 0 0 / 0.9); }
.gam-hist-in { display: flex; flex-direction: column; gap: 10px; padding: 12px 8px 8px; border-radius: 20px; background: linear-gradient(180deg, var(--am-s), color-mix(in srgb, var(--am-s) 96%, #000)); box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.9), 0 0 0 1px var(--am-line), 0 2px 4px -1px rgb(0 0 0 / 0.05); }
:root[data-glass-mode="dark"] .gam-hist-in { background: linear-gradient(180deg, #24242a, #1d1d22); box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.07), 0 0 0 1px rgb(0 0 0 / 0.5); }
.gam-hist-bar { display: flex; align-items: center; gap: 7px; padding: 0 4px 0 8px; }
.gam-hist-bar b { font-size: 15px; letter-spacing: -0.02em; }
.gam-hist-count { min-width: 20px; padding: 1px 6px; border-radius: 99px; font-size: 11px; font-weight: 600; text-align: center; color: var(--am-mute); background: var(--am-soft); font-variant-numeric: tabular-nums; }
.gam-hist-new { display: inline-flex; align-items: center; gap: 4px; height: 30px; margin-left: auto; padding: 0 11px 0 9px; border: 0; border-radius: 99px; font: inherit; font-size: 12.5px; font-weight: 600; color: var(--am-on); background: linear-gradient(180deg, color-mix(in srgb, var(--am-c) 78%, #fff), var(--am-c)); box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.3), 0 0 0 1px color-mix(in srgb, var(--am-c) 80%, #000), 0 4px 10px -5px var(--am-c); cursor: pointer; transition: transform 0.25s var(--am-spring); }
.gam-hist-new:active { transform: scale(0.94); }
