.gam-hist-search { display: flex; align-items: center; gap: 8px; height: 36px; margin: 0 2px; padding: 0 10px; border-radius: 11px; color: var(--am-mute); background: linear-gradient(180deg, rgb(0 0 0 / 0.045), rgb(0 0 0 / 0.02)); box-shadow: inset 0 1px 2px rgb(0 0 0 / 0.06), 0 1px 0 rgb(255 255 255 / 0.7); transition: box-shadow 0.2s; }
:root[data-glass-mode="dark"] .gam-hist-search { background: rgb(0 0 0 / 0.25); box-shadow: inset 0 1px 2px rgb(0 0 0 / 0.4), 0 1px 0 rgb(255 255 255 / 0.04); }
.gam-hist-search:focus-within { color: var(--am-c); box-shadow: inset 0 1px 2px rgb(0 0 0 / 0.04), 0 0 0 1px var(--am-c), 0 0 0 4px color-mix(in srgb, var(--am-c) 16%, transparent); }
.gam-hist-search input { flex: 1; min-width: 0; border: 0; font: inherit; font-size: 13.5px; color: var(--glass-fg); background: none; outline: none; }
.gam-hist-search input::placeholder { color: var(--am-mute); }
.gam-hist-search button { display: grid; place-items: center; width: 20px; height: 20px; padding: 0; border: 0; border-radius: 50%; color: var(--am-on); background: var(--am-mute); cursor: pointer; animation: gam-pop 0.25s var(--am-spring); }
.gam-hist-list { display: flex; flex-direction: column; gap: 10px; }
.gam-hist-group { display: flex; flex-direction: column; gap: 1px; }
.gam-hist-head { display: flex; align-items: center; gap: 5px; padding: 2px 10px 4px; font-size: 11px; font-weight: 600; letter-spacing: 0.03em; text-transform: uppercase; color: var(--am-mute); }
.gam-hist-row { position: relative; display: flex; align-items: center; border-radius: 11px; transition: background 0.15s, box-shadow 0.2s, opacity 0.28s, transform 0.28s var(--am-out), max-height 0.28s var(--am-out); max-height: 48px; animation: gam-rise 0.35s var(--am-out) backwards; animation-delay: calc(var(--i) * 25ms); }
.gam-hist-row:hover, .gam-hist-row[data-open] { background: var(--am-soft); }
.gam-hist-row[data-open] { z-index: 5; }
.gam-hist-row[aria-current="page"] { background: linear-gradient(180deg, #fff, #fafafa); box-shadow: inset 0 1px 0 #fff, 0 0 0 1px var(--am-line), 0 2px 6px -2px rgb(0 0 0 / 0.1); }
:root[data-glass-mode="dark"] .gam-hist-row[aria-current="page"] { background: linear-gradient(180deg, #303037, #29292f); box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.08), 0 0 0 1px rgb(0 0 0 / 0.5); }
.gam-hist-row[aria-current="page"]::before { content: ""; position: absolute; left: 10px; top: 50%; width: 6px; height: 6px; margin-top: -3px; border-radius: 50%; background: var(--am-c); box-shadow: 0 0 0 3px color-mix(in srgb, var(--am-c) 20%, transparent); }
.gam-hist-row[data-gone] { max-height: 0; opacity: 0; transform: translateX(-12px); }
.gam-hist-item { flex: 1; min-width: 0; display: flex; align-items: center; gap: 8px; height: 38px; padding: 0 10px; border: 0; font: inherit; font-size: 13.5px; text-align: left; color: color-mix(in srgb, var(--glass-fg) 82%, transparent); background: none; cursor: pointer; }
.gam-hist-row[aria-current="page"] .gam-hist-item { padding-left: 24px; font-weight: 500; color: var(--glass-fg); }
.gam-hist-t { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.gam-hist-t mark { border-radius: 3px; color: inherit; background: color-mix(in srgb, var(--am-c) 22%, transparent); }
.gam-hist-time { flex: none; font-style: normal; font-size: 11.5px; color: var(--am-mute); font-variant-numeric: tabular-nums; transition: opacity 0.15s; }
.gam-hist-row:hover .gam-hist-time, .gam-hist-row[data-open] .gam-hist-time { opacity: 0; }
.gam-hist-edit { flex: 1; height: 32px; margin: 3px 4px; padding: 0 8px; border: 0; border-radius: 8px; font: inherit; font-size: 13.5px; color: var(--glass-fg); background: var(--am-s); box-shadow: 0 0 0 1.5px var(--am-c), 0 0 0 4px color-mix(in srgb, var(--am-c) 16%, transparent); outline: none; }
.gam-hist-more-wrap { position: absolute; right: 4px; top: 50%; transform: translateY(-50%); }
.gam-hist-more { display: grid; place-items: center; width: 28px; height: 28px; padding: 0; border: 0; border-radius: 8px; color: var(--am-mute); background: none; cursor: pointer; opacity: 0; transition: opacity 0.15s, background 0.15s; }
.gam-hist-row:hover .gam-hist-more, .gam-hist-more[aria-expanded="true"], .gam-hist-more:focus-visible { opacity: 1; }
.gam-hist-more:hover, .gam-hist-more[aria-expanded="true"] { color: var(--glass-fg); background: rgb(var(--glass-shadow) / 0.08); }
.gam-hist-menu { position: absolute; right: 0; top: calc(100% + 6px); z-index: 30; display: flex; flex-direction: column; min-width: 168px; padding: 5px; border-radius: 14px; background: linear-gradient(180deg, var(--am-s), color-mix(in srgb, var(--am-s) 96%, #000)); box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.8), 0 0 0 1px var(--am-line), 0 20px 40px -14px rgb(0 0 0 / 0.35); animation: gam-pop 0.25s var(--am-spring); transform-origin: top right; }
:root[data-glass-mode="dark"] .gam-hist-menu { background: linear-gradient(180deg, #2a2a30, #232328); box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.07), 0 0 0 1px rgb(0 0 0 / 0.5), 0 20px 40px -14px rgb(0 0 0 / 0.8); }
.gam-hist-menu button { display: flex; align-items: center; gap: 9px; height: 34px; padding: 0 10px; border: 0; border-radius: 9px; font: inherit; font-size: 13.5px; color: var(--glass-fg); background: none; cursor: pointer; text-align: left; }
