/* ---------- Mentions ---------- */
.gam-men { position: relative; display: flex; flex-direction: column; gap: 8px; width: 100%; max-width: 520px; padding: 10px; border-radius: 20px; background: var(--am-s); box-shadow: inset 0 0 0 1px var(--am-line), 0 10px 26px -18px rgb(0 0 0 / 0.35); }
.gam-men-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.gam-men-chip { --k: var(--am-c); display: inline-flex; align-items: center; gap: 5px; height: 26px; padding: 0 4px 0 8px; border-radius: 8px; font-size: 12.5px; font-weight: 500; color: color-mix(in srgb, var(--k) 85%, var(--glass-fg)); background: color-mix(in srgb, var(--k) 11%, transparent); animation: gam-pop 0.25s var(--am-spring); }
.gam-men-chip[data-kind="person"] { --k: #2f8f5b; } .gam-men-chip[data-kind="tool"] { --k: #c56a12; } .gam-men-chip[data-kind="web"] { --k: #2563eb; }
.gam-men-chip button { display: grid; place-items: center; width: 18px; height: 18px; padding: 0; border: 0; border-radius: 5px; color: inherit; background: none; cursor: pointer; opacity: 0.7; }
.gam-men-chip button:hover { opacity: 1; background: color-mix(in srgb, var(--k) 16%, transparent); }
.gam-men-row { display: flex; align-items: flex-end; gap: 8px; }
.gam-men-row textarea { flex: 1; min-width: 0; resize: none; padding: 6px 6px; border: 0; font: inherit; font-size: 15px; line-height: 1.45; color: var(--glass-fg); background: none; outline: none; }
.gam-men-row textarea::placeholder { color: var(--am-mute); }
.gam-men-send { flex: none; display: grid; place-items: center; width: 34px; height: 34px; padding: 0; border: 0; border-radius: 50%; color: var(--am-on); background: var(--am-c); cursor: pointer; transition: opacity 0.2s, transform 0.25s var(--am-spring); }
.gam-men-send:disabled { opacity: 0.3; cursor: default; }
.gam-men-send:active:not(:disabled) { transform: scale(0.9); }
.gam-men-pop { max-height: 200px; overflow: auto; position: absolute; left: 10px; bottom: calc(100% + 6px); z-index: 30; width: min(300px, calc(100% - 20px)); margin: 0; padding: 4px; list-style: none; border-radius: 14px; background: var(--am-s); box-shadow: 0 0 0 1px var(--am-line), 0 16px 34px -14px rgb(0 0 0 / 0.4); animation: gam-pop 0.2s var(--am-spring); }
.gam-men-pop li { display: flex; align-items: center; gap: 9px; height: 38px; padding: 0 8px; border-radius: 10px; font-size: 13.5px; cursor: pointer; }
.gam-men-pop li[aria-selected="true"] { background: var(--am-soft); }
.gam-men-pop li b { flex: 1; font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.gam-men-pop li em { font-style: normal; font-size: 12px; color: var(--am-mute); }
.gam-men-ic { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 7px; color: var(--am-c); background: color-mix(in srgb, var(--am-c) 11%, transparent); }
.gam-men-ic[data-kind="person"] { color: #2f8f5b; background: rgb(47 143 91 / 0.12); } .gam-men-ic[data-kind="tool"] { color: #c56a12; background: rgb(197 106 18 / 0.12); } .gam-men-ic[data-kind="web"] { color: #2563eb; background: rgb(37 99 235 / 0.12); }

/* ---------- Artifact panel ---------- */
.gam-art { display: flex; flex-direction: column; min-height: 0; overflow: hidden; border-radius: 18px; background: var(--am-s); box-shadow: inset 0 0 0 1px var(--am-line), 0 18px 40px -26px rgb(0 0 0 / 0.45); }
.gam-art-head { display: flex; align-items: center; gap: 8px; padding: 10px 10px 10px 12px; border-bottom: 1px solid var(--am-line); }
.gam-art-ic { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; color: var(--am-c); background: color-mix(in srgb, var(--am-c) 11%, transparent); }
.gam-art-head { flex-wrap: wrap; }
.gam-art-head > b { flex: 1 1 120px; min-width: 0; overflow: hidden; font-size: 14px; font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }
.gam-art-vers { display: inline-flex; padding: 2px; border-radius: 9px; background: var(--am-soft); }
.gam-art-vers button { height: 24px; padding: 0 8px; border: 0; border-radius: 7px; font: inherit; font-size: 12px; font-weight: 500; color: var(--am-mute); background: none; cursor: pointer; }
.gam-art-vers button[aria-pressed="true"] { color: var(--glass-fg); background: var(--am-s); box-shadow: 0 1px 2px rgb(var(--glass-shadow) / 0.15); }
.gam-art-acts { display: inline-flex; gap: 2px; }
.gam-art-acts button { display: grid; place-items: center; width: 30px; height: 30px; padding: 0; border: 0; border-radius: 8px; color: var(--am-mute); background: none; cursor: pointer; }
.gam-art-acts button:hover { color: var(--glass-fg); background: var(--am-soft); }
.gam-art-body { flex: 1; min-height: 0; overflow: auto; padding: 16px 18px; animation: gam-rise 0.35s var(--am-out); }
.gam-art-body pre { margin: 0; font: 12.5px/1.6 var(--font-mono, ui-monospace, monospace); white-space: pre-wrap; }
.gam-art-doc { font-size: 14px; line-height: 1.6; white-space: pre-wrap; }

/* ---------- Suggested edits ---------- */
.gam-diff { display: flex; flex-direction: column; gap: 12px; width: 100%; max-width: 560px; padding: 14px 16px; border-radius: 18px; background: var(--am-s); box-shadow: inset 0 0 0 1px var(--am-line); }
.gam-diff-top { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px; }
.gam-diff-top b { font-size: 13.5px; font-weight: 600; }
.gam-diff-top span { display: inline-flex; gap: 6px; }
.gam-diff-text { margin: 0; font-size: 15px; line-height: 1.75; }
.gam-chg { position: relative; border-radius: 4px; }
.gam-chg del { padding: 1px 2px; border-radius: 4px; color: #b42318; background: rgb(229 72 77 / 0.12); text-decoration-color: rgb(229 72 77 / 0.6); }
.gam-chg ins { padding: 1px 2px; border-radius: 4px; color: #146c43; background: rgb(31 164 99 / 0.14); text-decoration: none; }
.gam-chg[data-s="yes"] ins, .gam-chg[data-s="no"] del { padding: 0; color: inherit; background: none; text-decoration: none; transition: background 0.6s; }
.gam-chg-acts { display: inline-flex; gap: 2px; margin-left: 3px; vertical-align: 1px; }
.gam-chg-acts button { display: inline-grid; place-items: center; width: 20px; height: 20px; padding: 0; border: 0; border-radius: 6px; color: #146c43; background: rgb(31 164 99 / 0.14); cursor: pointer; transition: transform 0.2s var(--am-spring); }
.gam-chg-acts button + button { color: #b42318; background: rgb(229 72 77 / 0.12); }
.gam-chg-acts button:hover { transform: scale(1.12); }
:root[data-glass-mode="dark"] .gam-chg del { color: #ff8b8f; } :root[data-glass-mode="dark"] .gam-chg ins { color: #6fe0a6; }
:root[data-glass-mode="dark"] .gam-chg-acts button { color: #6fe0a6; } :root[data-glass-mode="dark"] .gam-chg-acts button + button { color: #ff8b8f; }

/* ---------- Live waveform ---------- */
.gam-wave { display: flex; align-items: center; justify-content: center; gap: 3px; width: 100%; }
.gam-wave i { flex: 1; max-width: 5px; height: 100%; border-radius: 3px; background: var(--am-c); transform: scaleY(0.08); transform-origin: center; opacity: 0.9; }
.gam-wave:not([data-active]) i { opacity: 0.35; transition: transform 0.4s var(--am-out); }

/* ---------- Live transcript ---------- */
.gam-tr { display: flex; flex-direction: column; gap: 12px; max-height: 240px; overflow: auto; scroll-behavior: smooth; }
.gam-tr-line { display: flex; flex-direction: column; gap: 2px; margin: 0; font-size: 15px; line-height: 1.5; }
.gam-tr-line b { font-size: 11.5px; font-weight: 600; letter-spacing: 0.02em; color: var(--am-mute); }
.gam-tr-line[data-who="ai"] b { color: var(--am-c); }
.gam-tr-line:not([data-live]) { color: color-mix(in srgb, var(--glass-fg) 72%, transparent); }
.gam-tr-w { animation: gam-word 0.35s var(--am-out) backwards; }
.gam-tr-line[data-live] .gam-tr-w:last-of-type { color: var(--am-c); }
@keyframes gam-word { from { opacity: 0; filter: blur(4px); } }
.gam-tr-caret { display: inline-block; width: 2px; height: 1em; margin-left: 1px; vertical-align: -0.15em; border-radius: 1px; background: var(--am-c); animation: gam-blink 1s steps(1) infinite; }
@keyframes gam-blink { 50% { opacity: 0; } }

/* ---------- Voice picker ---------- */
.gam-vp { display: flex; flex-direction: column; gap: 6px; width: 100%; max-width: 380px; }
.gam-vp-row { display: flex; align-items: center; gap: 6px; padding: 4px; border-radius: 16px; background: var(--am-s); box-shadow: inset 0 0 0 1px var(--am-line); transition: box-shadow 0.2s; }
.gam-vp-row[data-on] { box-shadow: inset 0 0 0 1.5px var(--am-c), 0 6px 16px -10px color-mix(in srgb, var(--am-c) 60%, transparent); }
.gam-vp-pick { flex: 1; min-width: 0; display: flex; align-items: center; gap: 10px; padding: 6px; border: 0; border-radius: 12px; font: inherit; text-align: left; color: var(--glass-fg); background: none; cursor: pointer; }
.gam-vp-av { position: relative; flex: none; width: 38px; height: 38px; overflow: hidden; border-radius: 50%; background: radial-gradient(80% 80% at 30% 25%, hsl(var(--h) 90% 85%), hsl(var(--h) 70% 60%)); }
.gam-vp-av i { position: absolute; inset: 30%; border-radius: 50%; background: hsl(calc(var(--h) + 50) 90% 75% / 0.8); filter: blur(4px); animation: gam-blob 5s ease-in-out infinite; }
.gam-vp-av i:nth-child(2) { inset: 45% 15% 15% 45%; background: hsl(calc(var(--h) - 40) 90% 70% / 0.8); animation-delay: -1.5s; }
.gam-vp-av i:nth-child(3) { inset: 10% 50% 50% 10%; background: rgb(255 255 255 / 0.7); animation-delay: -3s; }
@keyframes gam-blob { 50% { transform: translate(18%, -12%) scale(1.2); } }
.gam-vp-txt { flex: 1; min-width: 0; display: flex; flex-direction: column; line-height: 1.3; }
.gam-vp-txt b { font-size: 14px; font-weight: 600; }
.gam-vp-txt em { overflow: hidden; font-style: normal; font-size: 12.5px; color: var(--am-mute); text-overflow: ellipsis; white-space: nowrap; }
.gam-vp-tick { display: grid; place-items: center; width: 20px; height: 20px; border-radius: 50%; color: var(--am-on); background: var(--am-c); transform: scale(0); transition: transform 0.3s var(--am-spring); }
.gam-vp-row[data-on] .gam-vp-tick { transform: scale(1); }
.gam-vp-play { flex: none; display: grid; place-items: center; width: 36px; height: 36px; margin-right: 4px; padding: 0; border: 0; border-radius: 50%; color: var(--glass-fg); background: var(--am-soft); cursor: pointer; transition: transform 0.25s var(--am-spring), background 0.2s; }
.gam-vp-play:hover { background: rgb(var(--glass-shadow) / 0.1); }
.gam-vp-play:active { transform: scale(0.9); }
.gam-vp-play[data-playing] { color: var(--am-on); background: var(--am-c); }
.gam-vp-eq { display: flex; align-items: center; gap: 2px; height: 12px; }
.gam-vp-eq i { width: 2.5px; height: 100%; border-radius: 2px; background: currentColor; animation: gam-eq 0.7s ease-in-out infinite; }
.gam-vp-eq i:nth-child(2) { animation-delay: -0.25s; } .gam-vp-eq i:nth-child(3) { animation-delay: -0.45s; }
@keyframes gam-eq { 50% { transform: scaleY(0.35); } }

/* ---------- Audio player ---------- */
.gam-ap { display: flex; flex-direction: column; gap: 12px; width: 100%; max-width: 520px; padding: 12px 14px 12px 12px; border-radius: 20px; background: var(--am-s); box-shadow: inset 0 0 0 1px var(--am-line), 0 12px 28px -20px rgb(0 0 0 / 0.4); }
.gam-ap-row { display: flex; align-items: center; gap: 12px; }
.gam-ap-play { flex: none; display: grid; place-items: center; width: 42px; height: 42px; padding: 0; border: 0; border-radius: 50%; color: var(--am-on); background: var(--am-c); cursor: pointer; box-shadow: 0 6px 14px -8px var(--am-c); transition: transform 0.25s var(--am-spring); }
.gam-ap-play:active { transform: scale(0.9); }
.gam-ap-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.gam-ap-title { font-size: 13px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.gam-ap-wave { display: flex; align-items: center; gap: 2px; height: 32px; cursor: pointer; touch-action: none; outline: none; }
.gam-ap-wave:focus-visible { box-shadow: 0 0 0 2px var(--am-c); border-radius: 4px; }
.gam-ap-wave i { flex: 1; min-width: 1px; border-radius: 2px; background: rgb(var(--glass-shadow) / 0.18); transition: background 0.15s; }
.gam-ap-wave i[data-past] { background: var(--am-c); }
:root[data-glass-mode="dark"] .gam-ap-wave i:not([data-past]) { background: rgb(255 255 255 / 0.18); }
.gam-ap-time { flex: none; font-size: 12px; font-variant-numeric: tabular-nums; color: var(--am-mute); }
.gam-ap-rate { flex: none; min-width: 40px; height: 28px; padding: 0 8px; border: 0; border-radius: 8px; font: inherit; font-size: 12px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--glass-fg); background: var(--am-soft); cursor: pointer; }
.gam-ap-words { margin: 0; padding: 0 2px; font-size: 15px; line-height: 1.6; color: var(--am-mute); }
.gam-ap-words span { transition: color 0.2s; border-radius: 4px; }
.gam-ap-words span[data-s="past"] { color: var(--glass-fg); }
.gam-ap-words span[data-s="now"] { color: var(--glass-fg); background: color-mix(in srgb, var(--am-c) 16%, transparent); box-shadow: 0 0 0 2px color-mix(in srgb, var(--am-c) 16%, transparent); }
@media (max-width: 480px) { .gam-ap-time { display: none; } }

@media (prefers-reduced-motion: reduce) {
  :is(.gam-br-body, .gam-fu-list button, .gam-err, .gam-men-chip, .gam-art-body, .gam-tr-w, .gam-vp-av i, .gam-vp-eq i, .gam-sel-bar, .gam-hist-menu, .gam-men-pop) { animation: none !important; }
}

/* ---------- Phones: menus open as sheets from the bottom; small buttons get bigger touch areas ---------- */
@keyframes g-sheet-up { from { translate: 0 110%; } }
@media (max-width: 640px) {
  :is(.gam-hist-menu) { position: fixed !important; left: 8px !important; right: 8px !important; bottom: calc(8px + env(safe-area-inset-bottom)) !important; top: auto !important; width: auto !important; min-width: 0 !important; max-width: none !important; max-height: 72vh !important; overflow: auto !important; transform: none !important; z-index: 1000 !important; margin: 0 !important; padding-top: 22px !important; border-radius: 26px !important; box-shadow: 0 0 0 100vmax rgb(10 10 14 / 0.38), 0 -10px 40px -10px rgb(0 0 0 / 0.35) !important; animation: g-sheet-up 0.45s cubic-bezier(0.3, 1.4, 0.5, 1) !important; }
  :is(.gam-hist-menu)::before { content: ""; position: absolute; top: 8px; left: 50%; width: 38px; height: 5px; margin-left: -19px; border-radius: 9px; background: rgb(128 128 140 / 0.35); }
}
@media (pointer: coarse) {
  :is(.gam-br-nav button, .gam-hist-more, .gam-chg-acts button) { position: relative; }
  :is(.gam-br-nav button, .gam-hist-more, .gam-chg-acts button)::after { content: ""; position: absolute; inset: -9px; }
  .gam-hist-more { opacity: 1; }
  .gam-hist-item { height: 42px; }
}
